// Type returns the type of the active variant, or an empty type when there is none.
func (u Action) Type() ActionType {
	switch u.Variant.(type) {
	case CreatePayload:
		return CreateActionType
	case SetPayload:
		return SetActionType
	case RemovePayload:
		return RemoveActionType
	case InsertPayload:
		return InsertActionType
	case MovePayload:
		return MoveActionType
	case AddRowPayload:
		return AddRowActionType
	case RemoveRowPayload:
		return RemoveRowActionType
	case AddColPayload:
		return AddColActionType
	case RemoveColPayload:
		return RemoveColActionType
	case ResizeRowPayload:
		return ResizeRowActionType
	case ResizeColPayload:
		return ResizeColActionType
	case MoveRowPayload:
		return MoveRowActionType
	case MoveColPayload:
		return MoveColActionType
	case SetCellPayload:
		return SetCellActionType
	case EraseCellsPayload:
		return EraseCellsActionType
	}
	return ""
}

// ApplyDefaults fills the active variant's zero-valued fields with their
// schema-declared defaults.
func (u *Action) ApplyDefaults() {
	switch variant := u.Variant.(type) {
	case CreatePayload:
		variant.ApplyDefaults()
		u.Variant = variant
	case AddRowPayload:
		variant.ApplyDefaults()
		u.Variant = variant
	case AddColPayload:
		variant.ApplyDefaults()
		u.Variant = variant
	case SetCellPayload:
		variant.ApplyDefaults()
		u.Variant = variant
	case EraseCellsPayload:
		variant.ApplyDefaults()
		u.Variant = variant
	}
}

// Validate returns an error wrapping validate.ErrValidation if the active variant
// violates its schema constraints.
func (u Action) Validate() error {
	switch variant := u.Variant.(type) {
	case CreatePayload:
		return variant.Validate()
	case AddRowPayload:
		return variant.Validate()
	case AddColPayload:
		return variant.Validate()
	case SetCellPayload:
		return variant.Validate()
	case EraseCellsPayload:
		return variant.Validate()
	}
	return nil
}

// Update holds changes to the fields of the table. An absent field does not change.
type Update struct {
	// Name is a human-readable name for the table.
	Name *string `json:"name,omitzero" msgpack:"name,omitempty"`
	// Group is the group the table sits in, if any.
	Group patch.Change[group.Key] `json:"group,omitzero" msgpack:"group,omitempty"`
	// Project is the project that owns the table, if any. Exactly one of project and
	// range is set.
	Project patch.Change[project.Key] `json:"project,omitzero" msgpack:"project,omitempty"`
}

// EncodeMsgpack implements msgpack.CustomEncoder.
func (u Update) EncodeMsgpack(enc *vmsgpack.Encoder) error {
	return patch.EncodeMsgpack(enc, u)
}

// DecodeMsgpack implements msgpack.CustomDecoder.
func (u *Update) DecodeMsgpack(dec *vmsgpack.Decoder) error {
	return patch.DecodeMsgpack(dec, u)
}
